SELECT c.SEC_SNAME AS `股票简称`, c.SEC_CODE AS `股票代码`, ROUND(SUM(s.TOT_ACCUM_DIV) / 100000000, 2) AS `最近三年累计分红(亿元)` FROM STK_DIV_STAT s JOIN GET_A_SEC_CODE c ON s.COMCODE = c.COMCODE AND c.ISVALID = 1 WHERE s.ISVALID = 1 AND s.DIV_YEAR >= 2023 AND s.DIV_YEAR <= 2025 AND s.TOT_ACCUM_DIV IS NOT NULL GROUP BY c.SEC_SNAME, c.SEC_CODE ORDER BY `最近三年累计分红(亿元)` DESC LIMIT 5;
